    var e = m[k];
    if (!e) { m[k] = [c[i], t[i], has ? o[i] : NaN, has ? h[i] : NaN, has ? l[i] : NaN]; continue; }
    if (has && isFinite(e[2])) { if (h[i] > e[3]) e[3] = h[i]; if (l[i] < e[4]) e[4] = l[i]; }
    else if (has && !isFinite(e[2])) { e[2] = o[i]; e[3] = h[i]; e[4] = l[i]; }
